style.css:
@-moz-document domain("pinterest.com") {
/* General Background */
    body, .GridPage, .container, .App {
        background-color: #fce4ec !important; /* Soft blush pink */
        color: #ec9ec0 !important; /* All text in soft pink */
    }

    /* Pin Grid */
    .pin {
        background-color: #f8e3eb !important; /* Light blush pink */
        color: #ec9ec0 !important; /* Pink text */
    }

    .pin:hover {
        background-color: #fcd9e6 !important; /* Slightly darker pink on hover */
    }

    /* Buttons */
    button, .pin-button, .button, .follow-button, .save-button {
        background-color: #ec9ec0 !important; /* Accent pink for buttons */
        color: white !important;
        border-radius: 5px !important;
    }

    button:hover, .pin-button:hover, .button:hover, .follow-button:hover, .save-button:hover {
        background-color: #d78ba9 !important; /* Darker pink on hover */
    }

    /* Links */
    a, .link {
        color: #ec9ec0 !important; /* Pink text for links */
        text-decoration: none !important;
    }

    a:hover, .link:hover {
        color: #d78ba9 !important; /* Darker pink on hover */
        text-decoration: underline !important;
    }

    /* Search Bar */
    .SearchBar, .SearchBox, .SearchBar input {
        background-color: #fde6ef !important; /* Soft blush pink for search bar */
        border: 1px solid #ec9ec0 !important;
        color: #ec9ec0 !important; /* Pink text in search bar */
    }

    /* Profile Section */
    .profile-header, .profile-header h1, .profile-header p {
        background-color: #fce4ec !important;
        color: #ec9ec0 !important; /* Pink text in profile section */
    }

    /* Navigation Menu */
    .nav, .side-nav, .nav-item {
        background-color: #f8e3eb !important; /* Light pink background for menu */
        color: #ec9ec0 !important; /* Pink text for menu items */
    }

    /* Footer */
    footer {
        background-color: #f8e3eb !important;
        color: #ec9ec0 !important; /* Pink footer text */
    }

    /* Grid Item Hover */
    .grid-item:hover {
        background-color: #fcd9e6 !important; /* Darker pink on hover */
        color: #ec9ec0 !important; /* Pink text on hover */
    }

    /* All Text (Headings, Paragraphs, etc.) */
    h1, h2, h3, h4, h5, h6, p, span, .text, .description {
        color: #ec9ec0 !important; /* All text styled in pink */
    }

    /* Story Section (if exists) */
    .story-header, .story-content {
        background-color: #f8e3eb !important;
        color: #ec9ec0 !important; /* Pink story text */
    }

    /* Board Section */
    .board, .board-header {
        background-color: #f8e3eb !important;
        color: #ec9ec0 !important; /* Pink text in board sections */
    }

    /* Input Fields */
    input, textarea, select {
        background-color: #fde6ef !important; /* Soft blush pink input fields */
        color: #ec9ec0 !important; /* Pink text in input fields */
        border: 1px solid #ec9ec0 !important; /* Pink border */
    }

    input:hover, textarea:hover, select:hover {
        border-color: #d78ba9 !important; /* Darker pink border on hover */
    }

    /* Modal and Popup Sections */
    .modal, .popup {
        background-color: #fce4ec !important;
        color: #ec9ec0 !important; /* Pink text in modals and popups */
    }
}
